INSERT INTO public.projects (id, title, slug, location, category, description, area, year, status, specifications, images) VALUES
('northwest-heights', 'Northwest Heights', 'northwest-heights', 'Tirupati, AP', 'Residential', 'A ultra-luxurious multi-family residential enclave combining cantilevered balconies, double-height floor-to-ceiling glass facades, and solar-smart roofing.', '14,500 sq.ft', '2025', 'Completed', ARRAY['Double-height living atrium', 'Private infinity deck', 'Smart home automation', 'VRF central air conditioning'], ARRAY['https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?q=80&w=1200&auto=format&fit=crop']),
('pineview-ridge', 'Pineview Ridge Residences', 'pineview-ridge-residences', 'Air By-Pass Road, Tirupati', 'Residential', 'A contemporary tropical villa featuring teak louvers, central open courtyard (Brahmasthan), water lily reflection pool, and Italian Statuario marble floors.', '9,800 sq.ft', '2025', 'Completed', ARRAY['Central courtyard pond', 'Custom teak woodwork', 'Italian Statuario flooring', '10kW rooftop solar grid'], ARRAY['https://images.unsplash.com/photo-1600585154526-990dced4db0d?q=80&w=1200&auto=format&fit=crop']),
('carrefour-new-building', 'Carrefour New Building', 'carrefour-new-building', 'Balaji Colony, Tirupati', 'Commercial', 'A modern commercial hub featuring high-traffic retail spaces, basement automated car parking, and glass curtain wall elevation.', '28,000 sq.ft', '2024', 'Completed', ARRAY['Curtain wall structural glazing', 'Automated basement parking', 'High-speed capsule elevators', 'Seismic Zone III compliance'], ARRAY['https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?q=80&w=1200&auto=format&fit=crop']),
('serene-haven-townhomes', 'Serene Haven Townhomes', 'serene-haven-townhomes', 'Renigunta Road, Tirupati', 'Architecture', 'A cluster of 12 luxury duplex townhomes boasting private terrace gardens, subterranean parking, and unified architectural elevation design.', '18,200 sq.ft', '2025', 'Completed', ARRAY['Private terrace gardens', 'Underground cabling network', 'Clubhouse & fitness suite', 'Rainwater harvesting shafts'], ARRAY['https://images.unsplash.com/photo-1600607687920-4e2a09cf159d?q=80&w=1200&auto=format&fit=crop']),
('science-laboratory-hall', 'Science Laboratory Hall', 'science-laboratory-hall', 'University Zone, Tirupati', 'Commercial', 'A high-precision research facility equipped with vibration-isolated foundation slabs, HEPA cleanroom HVAC ducts, and acid-resistant chemical flooring.', '22,000 sq.ft', '2024', 'Completed', ARRAY['Vibration isolated foundation', 'Acid-resistant epoxy flooring', 'HEPA cleanroom ventilation', 'Emergency gas containment'], ARRAY['https://images.unsplash.com/photo-1562774053-701939374585?q=80&w=1200&auto=format&fit=crop']),
('northwest-building', 'The Northwest Building', 'the-northwest-building', 'Chittoor Highway, AP', 'Renovation', 'Complete structural retrofitting and modern glass facade transformation of a 20-year-old concrete building into a LEED-certified workspace.', '16,000 sq.ft', '2025', 'Completed', ARRAY['CFRP structural strengthening', 'HPL louver shading', 'Smart lighting controls', 'Zero operational downtime during retrofitting'], ARRAY['https://images.unsplash.com/photo-1541888946425-d0fbb186a5b3?q=80&w=1200&auto=format&fit=crop'])
